insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('programming-languages', 'Programming Languages', 'Learn to think in code with the languages that run the world.', 'Start with the fundamentals — syntax, variables, functions, data structures and error handling — then go deep on object-oriented design, concurrency and idiomatic, production-quality code. Every language is organised from first program to advanced concepts, with official documentation first.', 'braces', 'amber', 1) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('web-development', 'Web Development', 'Build fast, accessible products for the browser and the server.', 'From semantic HTML to distributed backends. The frontend track covers HTML, CSS, JavaScript, TypeScript, React and Next.js alongside accessibility, performance and testing. The backend track covers Node.js, APIs, authentication, security, caching, queues and deployment.', 'globe', 'blue', 2) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('cloud-computing', 'Cloud Computing', 'Understand the cloud, then build on Azure, AWS and Google Cloud.', 'Learn the concepts that every provider shares — service models, virtualisation, compute, storage, networking, identity, high availability and cost — before specialising in Microsoft Azure, Amazon Web Services or Google Cloud with official learning paths, labs and certification guides.', 'cloud', 'sky', 3) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('devops', 'DevOps & Infrastructure', 'Ship reliably: Linux, containers, automation and observability.', 'A deliberate sequence from the command line and Git to Docker, Kubernetes, CI/CD, infrastructure as code and monitoring — finishing with deployment strategies on real cloud platforms.', 'infinity', 'emerald', 4) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('databases', 'Databases & Data', 'Model, query, tune and protect the data your software depends on.', 'SQL first, then PostgreSQL, MySQL, SQL Server, MongoDB and Redis. Learn design (ER diagrams, normalisation, relationships), performance (indexing, transactions, query plans), administration and security, and the data-engineering foundations of warehousing and ETL/ELT.', 'database', 'violet', 5) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('computer-science', 'Computer Science', 'The foundations that make every other skill easier.', 'University-level material on data structures, algorithms and complexity, programming paradigms and design patterns, operating systems, networks, architecture and assembly, software engineering and testing, system design, distributed systems, compilers, theory of computation and discrete mathematics.', 'cpu', 'rose', 6) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('mobile-development', 'Mobile Development', 'Native Android and iOS, or one codebase for both.', 'Android with Kotlin and Jetpack Compose, iOS with Swift and SwiftUI, and cross-platform apps with Flutter or React Native and Expo. Every track covers architecture, networking, local storage, testing and publishing to the stores.', 'smartphone', 'teal', 7) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('ai-machine-learning', 'AI & Machine Learning', 'From the maths of learning to building with large language models.', 'Three clearly separated layers: AI foundations (Python, mathematics, statistics, NumPy and pandas), machine and deep learning (classical ML, neural networks, PyTorch, TensorFlow, NLP and computer vision), and modern AI engineering (LLMs, prompt engineering, RAG, agents, evaluation and MLOps).', 'brain-circuit', 'indigo', 8) on conflict (slug) do nothing;
insert into public.departments (slug, name, tagline, description, icon, accent, sort_order) values ('ui-ux-design', 'UI/UX Design', 'Design interfaces people understand, enjoy and can actually use.', 'Design principles, typography, colour, layout and hierarchy; user research, personas and journeys; wireframing, prototyping and Figma; and the systems, accessibility and handoff practices that turn designs into shipped products.', 'palette', 'orange', 9) on conflict (slug) do nothing;
