insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('python', 'Python', 'Readable, batteries-included language for automation, data, AI and the web.', 'Python is the most widely taught first language and the default language of data science and machine learning. Its clear syntax lets beginners focus on problem solving, while its ecosystem scales to web backends, automation and research.', (select id from public.departments where slug = 'programming-languages'), 'https://docs.python.org/3/', array['Introduction and setup', 'Syntax and core concepts', 'Variables and data types', 'Control flow', 'Functions', 'Object-oriented programming', 'Data structures', 'Error handling and exceptions', 'Modules, packages and virtual environments', 'Iterators, generators and decorators', 'Typing and testing', 'Projects']::text[], 'terminal', true, 1) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('java', 'Java', 'Strongly typed, object-oriented language behind enterprise and Android software.', 'Java powers large backend systems, financial services and much of Android. Learning it builds a solid understanding of static typing, object-oriented design, the JVM and concurrency.', (select id from public.departments where slug = 'programming-languages'), 'https://dev.java/', array['Introduction and the JDK', 'Syntax, variables and types', 'Control flow and methods', 'Classes and objects', 'Inheritance, interfaces and polymorphism', 'Collections framework', 'Exceptions', 'Generics and lambdas', 'Streams API', 'Concurrency', 'Build tools and testing', 'Projects']::text[], 'coffee', true, 2) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('c', 'C', 'The minimal, close-to-the-metal language behind operating systems and embedded devices.', 'C teaches how programs really use memory: pointers, the stack and heap, and manual resource management. It is the language of operating system kernels, embedded firmware and many language runtimes.', (select id from public.departments where slug = 'programming-languages'), 'https://www.open-std.org/jtc1/sc22/wg14/', array['Compiling and running C', 'Variables, types and operators', 'Control flow', 'Functions', 'Arrays and strings', 'Pointers and memory', 'Structs and unions', 'Dynamic memory allocation', 'File I/O', 'Error handling', 'The preprocessor and build systems', 'Projects']::text[], 'binary', false, 3) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('cpp', 'C++', 'High-performance language for games, systems, finance and real-time software.', 'Modern C++ combines low-level control with powerful abstractions: classes, templates, RAII and the standard library. It is used wherever performance is critical, from game engines to trading systems.', (select id from public.departments where slug = 'programming-languages'), 'https://isocpp.org/', array['Toolchains and compiling', 'Types, variables and control flow', 'Functions and references', 'Classes and object-oriented design', 'RAII and resource management', 'Smart pointers', 'The standard library and containers', 'Templates and generic programming', 'Error handling and exceptions', 'Move semantics', 'Concurrency', 'Projects']::text[], 'cpu', true, 4) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('javascript', 'JavaScript', 'The language of the web, running in every browser and on the server with Node.js.', 'JavaScript makes web pages interactive and, through Node.js, also runs servers and tooling. Understanding closures, the event loop, promises and modules is essential for any web developer.', (select id from public.departments where slug = 'programming-languages'), 'https://developer.mozilla.org/en-US/docs/Web/JavaScript', array['Introduction and the browser console', 'Variables, types and operators', 'Control flow', 'Functions and scope', 'Objects and arrays', 'Closures and this', 'Prototypes and classes', 'Error handling', 'The DOM and events', 'Asynchronous JavaScript: promises and async/await', 'Modules', 'Projects']::text[], 'file-code', true, 5) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('typescript', 'TypeScript', 'JavaScript with a static type system for safer, more maintainable code.', 'TypeScript adds types to JavaScript, catching mistakes before code runs and making large codebases easier to navigate and refactor. It is now the default for professional frontend and Node.js work.', (select id from public.departments where slug = 'programming-languages'), 'https://www.typescriptlang.org/', array['Why TypeScript and setup', 'Basic types', 'Functions', 'Objects, interfaces and type aliases', 'Unions and narrowing', 'Generics', 'Classes', 'Modules', 'Utility and mapped types', 'Declaration files', 'Configuring tsconfig', 'Projects']::text[], 'file-type', true, 6) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('csharp', 'C#', 'Microsoft''s modern, multi-paradigm language for .NET, games and cloud services.', 'C# is the main language of the .NET platform, used for web APIs with ASP.NET Core, desktop apps, cloud services on Azure and game development with Unity.', (select id from public.departments where slug = 'programming-languages'), 'https://learn.microsoft.com/en-us/dotnet/csharp/', array['The .NET SDK and first program', 'Types and variables', 'Control flow', 'Methods', 'Classes, structs and records', 'Inheritance and interfaces', 'Collections and LINQ', 'Exceptions', 'Generics', 'Async and await', 'Testing', 'Projects']::text[], 'hash', false, 7) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('go', 'Go', 'Simple, fast, statically typed language built for cloud services and tooling.', 'Go was designed at Google for building reliable networked software. Its small language, fast compiler and built-in concurrency make it the language of Docker, Kubernetes and much cloud infrastructure.', (select id from public.departments where slug = 'programming-languages'), 'https://go.dev/', array['Installing Go and modules', 'Variables, types and constants', 'Control flow', 'Functions and multiple returns', 'Structs and methods', 'Interfaces', 'Slices and maps', 'Error handling', 'Goroutines and channels', 'Packages and testing', 'Generics', 'Projects']::text[], 'rabbit', false, 8) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('html', 'HTML', 'The semantic structure of every web page.', 'HTML describes the meaning and structure of content. Writing semantic HTML is the foundation of accessible, search-friendly and maintainable websites.', (select id from public.departments where slug = 'web-development'), 'https://developer.mozilla.org/en-US/docs/Web/HTML', array['Document structure', 'Text and semantics', 'Links and navigation', 'Images and media', 'Lists and tables', 'Forms and validation', 'Semantic layout elements', 'Accessibility basics', 'Metadata and SEO']::text[], 'code-xml', true, 9) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('css', 'CSS', 'Styling, layout and responsive design for the web.', 'CSS controls how HTML looks: colour, typography, spacing and layout. Modern CSS with Flexbox, Grid, custom properties and container queries can build almost any interface without frameworks.', (select id from public.departments where slug = 'web-development'), 'https://developer.mozilla.org/en-US/docs/Web/CSS', array['Selectors and the cascade', 'The box model', 'Typography and colour', 'Flexbox', 'CSS Grid', 'Responsive design and media queries', 'Custom properties', 'Transitions and animations', 'Container queries', 'Architecture and naming']::text[], 'paintbrush', true, 10) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('react', 'React', 'The component library for building interactive user interfaces.', 'React lets you build interfaces from small, reusable components that describe what the UI should look like for a given state. It is the most widely used frontend library.', (select id from public.departments where slug = 'web-development'), 'https://react.dev/', array['Thinking in components', 'JSX', 'Props and state', 'Rendering lists and conditions', 'Events', 'Hooks: useState and useEffect', 'Managing state', 'Context', 'Refs', 'Server Components', 'Performance', 'Testing components']::text[], 'atom', true, 11) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('nextjs', 'Next.js', 'The React framework for full-stack web applications.', 'Next.js adds routing, server rendering, data fetching, caching and deployment conventions on top of React, so teams can build complete production applications.', (select id from public.departments where slug = 'web-development'), 'https://nextjs.org/', array['The App Router', 'Layouts and pages', 'Server and Client Components', 'Data fetching', 'Caching and revalidation', 'Server Actions and mutations', 'Route handlers', 'Authentication patterns', 'Metadata and SEO', 'Images and fonts', 'Deployment']::text[], 'layers', true, 12) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('responsive-design', 'Responsive Design', 'Interfaces that adapt to every screen, from phones to wide monitors.', 'Responsive design uses fluid layouts, flexible media and breakpoints chosen by content so the same site works well on phones, tablets and desktops.', (select id from public.departments where slug = 'web-development'), 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/CSS_layout/Responsive_Design', array['Mobile-first thinking', 'Viewport and media queries', 'Fluid typography and spacing', 'Flexible grids', 'Responsive images', 'Container queries', 'Touch targets', 'Testing on devices']::text[], 'monitor-smartphone', false, 13) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('state-management', 'State Management', 'Patterns and libraries for keeping UI state predictable.', 'As applications grow, deciding where state lives — local, lifted, context, URL, server cache or a global store — becomes one of the most important architectural decisions.', (select id from public.departments where slug = 'web-development'), null, array['Local vs shared state', 'Lifting state up', 'Context', 'URL as state', 'Server state and caching', 'Reducers', 'Global stores', 'Derived state']::text[], 'workflow', false, 14) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('frontend-architecture', 'Frontend Architecture', 'Structuring large frontend codebases so teams can move fast safely.', 'Frontend architecture covers project structure, component boundaries, rendering strategies, data flow, design systems and tooling choices for applications that live for years.', (select id from public.departments where slug = 'web-development'), null, array['Project structure', 'Component design', 'Rendering strategies (CSR, SSR, SSG)', 'Data fetching patterns', 'Design systems', 'Monorepos', 'Build tooling', 'Micro-frontends']::text[], 'blocks', false, 15) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('web-accessibility', 'Web Accessibility', 'Building products that everyone can use, including people with disabilities.', 'Accessibility (a11y) ensures people using screen readers, keyboards, magnification or other assistive technologies can use your product. WCAG is the international standard.', (select id from public.departments where slug = 'web-development'), 'https://www.w3.org/WAI/', array['Why accessibility matters', 'WCAG principles (POUR)', 'Semantic HTML', 'Keyboard navigation and focus', 'Colour contrast', 'ARIA, used correctly', 'Accessible forms', 'Testing with screen readers', 'Automated audits']::text[], 'accessibility', false, 16) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('web-performance', 'Web Performance', 'Fast loading and responsive interaction, measured with Core Web Vitals.', 'Performance directly affects user satisfaction and conversion. Learn to measure LCP, INP and CLS, then optimise images, fonts, JavaScript and caching.', (select id from public.departments where slug = 'web-development'), 'https://web.dev/explore/learn-core-web-vitals', array['Core Web Vitals', 'Measuring in the lab and field', 'Images and media', 'Fonts', 'JavaScript cost', 'Caching and CDNs', 'Rendering strategies', 'Performance budgets']::text[], 'gauge', false, 17) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('frontend-testing', 'Frontend Testing', 'Unit, component and end-to-end tests for user interfaces.', 'Good frontend tests exercise behaviour the way users do. Learn the testing pyramid, component testing with Testing Library and browser automation with Playwright.', (select id from public.departments where slug = 'web-development'), 'https://testing-library.com/', array['The testing pyramid', 'Unit tests', 'Component tests', 'Mocking network requests', 'End-to-end tests', 'Visual regression', 'Accessibility checks', 'Testing in CI']::text[], 'flask-conical', false, 18) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('nodejs', 'Node.js', 'JavaScript on the server, built on an event-driven, non-blocking runtime.', 'Node.js runs JavaScript outside the browser. Its event loop and huge package ecosystem make it a popular choice for APIs, real-time services and developer tooling.', (select id from public.departments where slug = 'web-development'), 'https://nodejs.org/en', array['Installing Node and npm', 'Modules', 'The event loop', 'File system and streams', 'HTTP servers', 'Packages and npm', 'Environment and configuration', 'Error handling', 'Testing', 'Security best practices']::text[], 'hexagon', true, 19) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('express', 'Express.js', 'Minimal, flexible web framework for Node.js.', 'Express provides routing and middleware for building HTTP APIs and web apps on Node.js. Its simplicity makes it the best place to learn how backends handle requests.', (select id from public.departments where slug = 'web-development'), 'https://expressjs.com/', array['Routing', 'Middleware', 'Request and response', 'Error handling', 'Serving static files', 'Templating', 'Security middleware', 'Structuring larger apps']::text[], 'route', false, 20) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('rest-apis', 'REST APIs', 'Designing resource-oriented HTTP APIs.', 'REST is the dominant style for web APIs. Good API design covers resources, HTTP methods and status codes, pagination, versioning, errors and documentation with OpenAPI.', (select id from public.departments where slug = 'web-development'), 'https://openapis.org/', array['HTTP fundamentals', 'Resources and URLs', 'Methods and status codes', 'Request validation', 'Pagination and filtering', 'Versioning', 'Error formats', 'OpenAPI documentation']::text[], 'plug', false, 21) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('graphql', 'GraphQL', 'A query language that lets clients ask for exactly the data they need.', 'GraphQL exposes a typed schema that clients query precisely. Learn schemas, resolvers, queries, mutations and subscriptions, and the performance and security trade-offs.', (select id from public.departments where slug = 'web-development'), 'https://graphql.org/', array['Schemas and types', 'Queries', 'Mutations', 'Resolvers', 'Pagination', 'Subscriptions', 'N+1 and batching', 'Security and limits']::text[], 'share-2', false, 22) on conflict (slug) do nothing;
