insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('cloud-fundamentals', 'Cloud Fundamentals', 'Provider-neutral concepts every cloud engineer needs.', 'What cloud computing is; IaaS, PaaS and SaaS; public, private and hybrid clouds; virtualisation; compute, storage and networking; scalability and high availability; identity, security and the shared responsibility model; and pricing.', (select id from public.departments where slug = 'cloud-computing'), null, array['What is cloud computing?', 'IaaS, PaaS and SaaS', 'Public, private and hybrid clouds', 'Virtualisation', 'Compute services', 'Storage', 'Networking', 'Scalability and elasticity', 'High availability and disaster recovery', 'Cloud security and shared responsibility', 'Identity and access management (IAM)', 'Pricing and cost management']::text[], 'cloud', true, 31) on conflict (slug) do nothing;
