insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('ux-fundamentals', 'UI/UX Fundamentals', 'What UX and UI design are, and the principles behind good interfaces.', 'Usability heuristics, mental models, affordances, feedback and the design process from discovery to delivery.', (select id from public.departments where slug = 'ui-ux-design'), null, array['UX vs UI', 'The design process', 'Usability heuristics', 'Mental models', 'Affordances and signifiers', 'Feedback and error prevention', 'Information architecture']::text[], 'mouse-pointer-click', true, 108) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('visual-design', 'Visual Design', 'Typography, colour, spacing, layout and visual hierarchy.', 'Visual design makes interfaces clear and attractive: type scales, colour systems with accessible contrast, spacing systems, grids and hierarchy.', (select id from public.departments where slug = 'ui-ux-design'), null, array['Design principles', 'Typography', 'Colour theory', 'Spacing and layout grids', 'Visual hierarchy', 'Iconography', 'Imagery']::text[], 'type', false, 109) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('user-research', 'User Research', 'Interviews, personas and journey maps grounded in real people.', 'Plan and run user interviews and surveys, synthesise findings, and capture them as personas, jobs-to-be-done and journey maps.', (select id from public.departments where slug = 'ui-ux-design'), null, array['Research planning', 'User interviews', 'Surveys', 'Synthesis and affinity mapping', 'Personas', 'User journeys', 'Jobs to be done']::text[], 'users', false, 110) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('usability-testing', 'Usability Testing', 'Watching people use your design and learning from it.', 'Plan moderated and unmoderated usability tests, write good tasks, observe without leading and turn findings into improvements.', (select id from public.departments where slug = 'ui-ux-design'), null, array['Test planning', 'Writing tasks', 'Moderated testing', 'Unmoderated testing', 'Think-aloud', 'Analysing findings']::text[], 'eye', false, 111) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('wireframing-prototyping', 'Wireframing & Prototyping', 'From low-fidelity sketches to interactive prototypes.', 'Sketch flows, build wireframes to explore structure, then create interactive prototypes to test ideas before building them.', (select id from public.departments where slug = 'ui-ux-design'), null, array['Sketching', 'User flows', 'Low-fidelity wireframes', 'High-fidelity mockups', 'Interactive prototypes', 'Testing prototypes']::text[], 'frame', false, 112) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('figma', 'Figma', 'The collaborative interface design tool.', 'Figma is the industry-standard tool for interface design, prototyping and design systems, with real-time collaboration.', (select id from public.departments where slug = 'ui-ux-design'), 'https://help.figma.com/hc/en-us', array['Frames and layers', 'Auto layout', 'Components and variants', 'Styles and variables', 'Prototyping', 'Dev Mode and handoff']::text[], 'pen-tool', true, 113) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('design-systems', 'Design Systems', 'Tokens, components and guidelines that scale design quality.', 'A design system combines design tokens, a component library, patterns and documentation so teams ship consistent interfaces faster.', (select id from public.departments where slug = 'ui-ux-design'), null, array['Design tokens', 'Component libraries', 'Patterns', 'Documentation', 'Governance', 'Accessibility in systems']::text[], 'component', false, 114) on conflict (slug) do nothing;
insert into public.technologies (slug, name, short_description, description, department_id, official_url, topics, icon, is_featured, sort_order) values ('design-handoff', 'Design Handoff', 'Turning designs into specifications engineers can build from.', 'Specify layout, tokens, states, responsive behaviour and edge cases so implementation matches intent.', (select id from public.departments where slug = 'ui-ux-design'), null, array['Specs and annotations', 'States and edge cases', 'Responsive behaviour', 'Tokens in code', 'Design QA']::text[], 'hand-helping', false, 115) on conflict (slug) do nothing;
