insert into public.resources (slug, title, description, url, department_id, subcategory_id, level, type, publisher, pricing, source_kind, language, duration_label, status, is_featured, url_status, url_http_status, url_checked_at, curator_note) values ('python-official-tutorial', 'The Python Tutorial', 'The official introduction to Python from the Python Software Foundation. Covers the interpreter, control flow, data structures, modules, input/output, errors and exceptions, and classes — the best first read alongside any course.', 'https://docs.python.org/3/tutorial/', (select id from public.departments where slug = 'programming-languages'), (select s.id from public.subcategories s join public.departments d on d.id = s.department_id where d.slug = 'programming-languages' and s.slug = 'general-purpose'), 'beginner', 'documentation', 'Python Software Foundation', 'free', 'official', 'English', null, 'published', true, 'ok', 200, '2026-11-22T20:24:23.276Z', null) on conflict (slug) do nothing;
insert into public.resources (slug, title, description, url, department_id, subcategory_id, level, type, publisher, pricing, source_kind, language, duration_label, status, is_featured, url_status, url_http_status, url_checked_at, curator_note) values ('python-standard-library', 'The Python Standard Library reference', 'Reference documentation for everything that ships with Python: built-in types and functions, collections, itertools, pathlib, datetime, json, asyncio and more. Learn to look things up here first.', 'https://docs.python.org/3/library/', (select id from public.departments where slug = 'programming-languages'), (select s.id from public.subcategories s join public.departments d on d.id = s.department_id where d.slug = 'programming-languages' and s.slug = 'general-purpose'), 'intermediate', 'documentation', 'Python Software Foundation', 'free', 'official', 'English', null, 'published', false, 'ok', 200, '2026-11-22T20:24:23.276Z', null) on conflict (slug) do nothing;
insert into public.resources (slug, title, description, url, department_id, subcategory_id, level, type, publisher, pricing, source_kind, language, duration_label, status, is_featured, url_status, url_http_status, url_checked_at, curator_note) values ('cs50-python', 'CS50''s Introduction to Programming with Python', 'Harvard''s beginner course on Python: functions, conditionals, loops, exceptions, libraries, unit tests, file I/O, regular expressions and object-oriented programming, with lectures and graded problem sets.', 'https://cs50.harvard.edu/python/', (select id from public.departments where slug = 'programming-languages'), (select s.id from public.subcategories s join public.departments d on d.id = s.department_id where d.slug = 'programming-languages' and s.slug = 'general-purpose'), 'beginner', 'course', 'Harvard University', 'free', 'community', 'English', null, 'published', true, 'ok', 200, '2026-11-22T20:24:23.276Z', null) on conflict (slug) do nothing;
insert into public.resources (slug, title, description, url, department_id, subcategory_id, level, type, publisher, pricing, source_kind, language, duration_label, status, is_featured, url_status, url_http_status, url_checked_at, curator_note) values ('fcc-python-full-course', 'Learn Python – Full Course for Beginners', 'A long-form video introduction to Python from freeCodeCamp.org that builds up from installing Python to variables, functions, loops, classes and small programs — ideal if you learn best by watching and coding along.', 'https://www.youtube.com/watch?v=rfscVS0vtbw', (select id from public.departments where slug = 'programming-languages'), (select s.id from public.subcategories s join public.departments d on d.id = s.department_id where d.slug = 'programming-languages' and s.slug = 'general-purpose'), 'beginner', 'video', 'freeCodeCamp.org', 'free', 'community', 'English', null, 'published', false, 'ok', 200, '2026-11-22T20:24:23.276Z', null) on conflict (slug) do nothing;
insert into public.resources (slug, title, description, url, department_id, subcategory_id, level, type, publisher, pricing, source_kind, language, duration_label, status, is_featured, url_status, url_http_status, url_checked_at, curator_note) values ('automate-the-boring-stuff', 'Automate the Boring Stuff with Python', 'Al Sweigart''s practical book, free to read online, that teaches Python by automating real tasks: working with files, spreadsheets, PDFs, web scraping and scheduling. Great for motivation and practical exercises.', 'https://automatetheboringstuff.com/', (select id from public.departments where slug = 'programming-languages'), (select s.id from public.subcategories s join public.departments d on d.id = s.department_id where d.slug = 'programming-languages' and s.slug = 'general-purpose'), 'beginner', 'book', 'Al Sweigart', 'free', 'community', 'English', null, 'published', false, 'ok', 200, '2026-11-22T20:24:23.276Z', null) on conflict (slug) do nothing;
