insert into public.roadmaps (slug, title, summary, description, department_id, level, estimated_duration, prerequisites, outcomes, certifications, icon, is_featured, status, sort_order) values ('python-developer', 'Python Developer', 'From first script to well-tested, packaged Python applications.', 'Learn Python properly: the language and its standard library, idiomatic code, testing and packaging, then specialise into web backends, automation or data. Suitable for complete beginners.', (select id from public.departments where slug = 'programming-languages'), 'beginner', '4–6 months', array['Basic computer literacy', 'No prior programming experience needed']::text[], array['Write clean, idiomatic Python', 'Structure, test and package projects', 'Build a web API or automation tool end to end']::text[], '[{"name":"PCEP – Certified Entry-Level Python Programmer","provider":"Python Institute","url":"https://pythoninstitute.org/pcep"}]'::jsonb, 'terminal', true, 'published', 1) on conflict (slug) do nothing;
insert into public.roadmap_stages (roadmap_id, position, title, summary, skills, projects, estimated_duration) select (select id from public.roadmaps where slug = 'python-developer'), 1, 'Programming fundamentals in Python', 'Variables, types, control flow, functions and core data structures through small exercises.', array['Variables and data types', 'Conditionals and loops', 'Functions', 'Lists, dictionaries, sets and tuples', 'Reading error messages']::text[], '[{"title":"Command-line quiz game","description":"A quiz that loads questions from a JSON file, tracks the score and handles invalid input gracefully."}]'::jsonb, '4–6 weeks' where not exists (select 1 from public.roadmap_stages where roadmap_id = (select id from public.roadmaps where slug = 'python-developer') and position = 1);
insert into public.roadmap_stage_technologies (stage_id, technology_id) values ((select id from public.roadmap_stages where roadmap_id = (select id from public.roadmaps where slug = 'python-developer') and position = 1), (select id from public.technologies where slug = 'python')) on conflict do nothing;
