insert into public.roadmap_stages (roadmap_id, position, title, summary, skills, projects, estimated_duration) select (select id from public.roadmaps where slug = 'python-developer'), 2, 'Developer tooling', 'Get comfortable with the command line and version control before anything else — every later stage assumes them.', array['Navigating the terminal', 'Editing files from the shell', 'Committing, branching and merging with Git', 'Pushing to GitHub and opening pull requests']::text[], '[{"title":"Dotfiles repository","description":"Version your shell and editor configuration in a public GitHub repository with a clear README."}]'::jsonb, '1–2 weeks' where not exists (select 1 from public.roadmap_stages where roadmap_id = (select id from public.roadmaps where slug = 'python-developer') and position = 2);
