insert into public.roadmaps (slug, title, summary, description, department_id, level, estimated_duration, prerequisites, outcomes, certifications, icon, is_featured, status, sort_order) values ('cloud-engineer', 'Cloud Engineer', 'Provider-neutral cloud foundations, then hands-on with a major platform.', 'Understand the cloud from first principles — service models, virtualisation, networking, identity, reliability and cost — using the priority Nexavena tutorial and official material, then build real infrastructure with code and automation.', (select id from public.departments where slug = 'cloud-computing'), 'beginner', '6–9 months', array['Basic computer literacy', 'Some exposure to the command line helps']::text[], array['Explain cloud concepts and trade-offs clearly', 'Deploy networked, secure workloads on a major provider', 'Automate infrastructure with code']::text[], '[{"name":"Azure Fundamentals (AZ-900)","provider":"Microsoft","url":"https://learn.microsoft.com/en-us/credentials/certifications/azure-fundamentals/"},{"name":"AWS Certified Cloud Practitioner","provider":"Amazon Web Services","url":"https://aws.amazon.com/certification/certified-cloud-practitioner/"},{"name":"Cloud Digital Leader","provider":"Google Cloud","url":"https://cloud.google.com/learn/certification/cloud-digital-leader"},{"name":"Associate Cloud Engineer","provider":"Google Cloud","url":"https://cloud.google.com/learn/certification/cloud-engineer"},{"name":"Professional Cloud Architect","provider":"Google Cloud","url":"https://cloud.google.com/learn/certification/cloud-architect"}]'::jsonb, 'cloud', true, 'published', 7) on conflict (slug) do nothing;
insert into public.roadmap_stages (roadmap_id, position, title, summary, skills, projects, estimated_duration) select (select id from public.roadmaps where slug = 'cloud-engineer'), 1, 'Cloud fundamentals', 'What the cloud is, service and deployment models, and how providers price and secure services.', array['IaaS, PaaS and SaaS', 'Public, private and hybrid clouds', 'Virtualisation', 'Shared responsibility', 'Consumption pricing']::text[], '[{"title":"Cloud concepts explainer","description":"Write a one-page guide comparing IaaS, PaaS and SaaS with a real example of each, and price a small web app in a pricing calculator."}]'::jsonb, '3–4 weeks' where not exists (select 1 from public.roadmap_stages where roadmap_id = (select id from public.roadmaps where slug = 'cloud-engineer') and position = 1);
